-- GDS Chain 묶음 복사: 로컬 DMSMGR SCK / OMM_TCB (2026-10-15 DWG Chain 도면 기준) -> 대상 DB 의 &factory / &device Map (2026-10-21)
-- Chain 19 / 포함 도형 62609 / 수동 편집 기록 34810. 생성: DMS/Assistant/DB/sql/make_u9_chain_copy.py
-- 대상 Map 은 같은 GDS(OMM all layer2.gds) + 같은 Layer(3/0, 5/0, 775/237)로 저장되어 있어야 한다.
-- 실행: 대상 사용자(예 TRAINING)로 접속해 @이 파일. 한 트랜잭션이라 오류가 나면 모두 되돌린다(ROLLBACK). 다시 실행하면 이미 만든 이름은 건너뛴다.
SET DEFINE ON
DEFINE factory = 'SCK'
DEFINE device = 'U9'
SET SERVEROUTPUT ON SIZE UNLIMITED
SET FEEDBACK OFF VERIFY OFF ECHO OFF
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
WHENEVER OSERROR EXIT FAILURE ROLLBACK
SPOOL u9_chain_copy_run.log
PROMPT === 대상: &factory / &device

-- 0) 사전 검사
DECLARE
  n NUMBER;
  PROCEDURE need_layer(p_layer NUMBER, p_type NUMBER) IS c NUMBER; BEGIN
    SELECT COUNT(*) INTO c FROM TQP_GDS_LAYER WHERE FACTORY = '&factory' AND DEVICE_ID = '&device' AND LAYER_ID = p_layer AND DATA_TYPE = p_type;
    IF c = 0 THEN RAISE_APPLICATION_ERROR(-20002, 'Layer ' || p_layer || '/' || p_type || ' 가 대상 Map 에 없습니다.'); END IF;
  END;
  PROCEDURE same_el(p_id VARCHAR2, p_layer NUMBER, p_type NUMBER, p_x VARCHAR2, p_y VARCHAR2) IS c NUMBER; BEGIN
    SELECT COUNT(*) INTO c FROM TQP_GDS_PLACED_EL WHERE FACTORY = '&factory' AND DEVICE_ID = '&device' AND PLACED_ELEMENT_ID = p_id
      AND LAYER_ID = p_layer AND DATA_TYPE = p_type
      AND MIN_X = UTL_RAW.CAST_TO_BINARY_DOUBLE(HEXTORAW(p_x)) AND MIN_Y = UTL_RAW.CAST_TO_BINARY_DOUBLE(HEXTORAW(p_y));
    IF c = 0 THEN RAISE_APPLICATION_ERROR(-20003, '시작 도형 ' || p_id || ' 이 없거나 위치 / Layer 가 원본과 다릅니다(다른 GDS 또는 다른 Layer 로 만든 Map).'); END IF;
  END;
BEGIN
  SELECT COUNT(*) INTO n FROM TQP_GDS_MAP WHERE FACTORY = '&factory' AND DEVICE_ID = '&device' AND MAP_STATUS = 'READY';
  IF n <> 1 THEN RAISE_APPLICATION_ERROR(-20001, 'READY 상태 GDS Map 이 없습니다: &factory / &device'); END IF;
  need_layer(3, 0);
  need_layer(5, 0);
  need_layer(775, 237);
  same_el('R0/E17264', 3, 0, 'C0C4DFC126E978D5', '40CC9189BA5E353F');
  same_el('R0/E17370', 3, 0, 'C0C4B7C126E978D5', '40CC4C416872B021');
  same_el('R0/E286194', 5, 0, '40C5C50000000000', '40CAA95147AE147B');
  same_el('R0/E16834', 3, 0, 'C0C57FC126E978D5', '40CA6747CED91687');
  same_el('R0/E18107', 3, 0, 'C0C39FC126E978D5', '40C7B275E353F7CF');
  same_el('R0/E18630', 3, 0, 'C0C2D7C126E978D5', '40C20389BA5E353F');
  same_el('R0/E18523', 3, 0, 'C0C2FFC126E978D5', '40C1BE416872B021');
  same_el('R0/E18620', 3, 0, 'C0C2D7C126E978D5', '40B933CA7EF9DB23');
  same_el('R0/E18513', 3, 0, 'C0C2FFC126E978D5', '40B8A93B22D0E560');
  same_el('R0/E18610', 3, 0, 'C0C2D7C126E978D5', '40ACC105A1CAC083');
  same_el('R0/E18503', 3, 0, 'C0C2FFC126E978D5', '40ABABE45A1CAC08');
  same_el('R0/E18600', 3, 0, 'C0C2D7C126E978D5', '408C69D916872B02');
  same_el('R0/E18590', 3, 0, 'C0C2D7C126E978D5', 'C09D18322D0E5604');
  same_el('R0/E254645', 5, 0, 'C085B00000000000', 'C0AB969EB851EB85');
  same_el('R0/E281659', 5, 0, '40C27D0000000000', 'C0ACABC000000000');
  same_el('R0/E19009', 3, 0, 'C0C237C126E978D5', 'C0ADB3E5E353F7CF');
  same_el('R0/E18441', 3, 0, 'C0C2FFC126E978D5', 'C0CAA3FF3B645A1D');
  same_el('R0/E18547', 3, 0, 'C0C2D7C126E978D5', 'C0CAE9478D4FDF3B');
  same_el('R0/E286945', 5, 0, '40C6650000000000', 'C0CC01A7AE147AE1');
  SELECT COUNT(*) INTO n FROM TQP_GDS_PLACED_EL WHERE FACTORY = '&factory' AND DEVICE_ID = '&device';
  DBMS_OUTPUT.PUT_LINE('사전 검사 통과: 대상 도형 ' || n || '개 (원본 Map 204898개) / Layer 3개 / 시작 도형 19개 위치 같음');
END;
/

