-- 1) Chain / 버전 / 탐색 Layer / 시작 도형(INPUT)
DECLARE
  n NUMBER; s NUMBER; c VARCHAR2(128); i NUMBER := 0;
  FUNCTION code_of(p NUMBER) RETURN VARCHAR2 IS x NUMBER := p; r VARCHAR2(10) := NULL; BEGIN
    LOOP r := CHR(65 + MOD(x, 26)) || r; x := TRUNC(x / 26) - 1; EXIT WHEN x < 0; END LOOP; RETURN r; END;
BEGIN
  SELECT COUNT(*) INTO n FROM TQP_GDS_CHAIN_VER WHERE FACTORY = '&factory' AND DEVICE_ID = '&device' AND CHAIN_NAME = 'TSVDC_TOP1_P_FH';
  IF n > 0 THEN
    :S_A := NULL;
    DBMS_OUTPUT.PUT_LINE('건너뜀(같은 이름 있음): ' || 'TSVDC_TOP1_P_FH');
  ELSE
    c := 'A';
    LOOP SELECT COUNT(*) INTO n FROM TQP_GDS_CHAIN WHERE FACTORY = '&factory' AND DEVICE_ID = '&device' AND CHAIN_CODE = c;
      EXIT WHEN n = 0; c := code_of(i); i := i + 1; END LOOP;
    SELECT CHAIN_SEQ.NEXTVAL INTO s FROM DUAL;
    :S_A := s;
    INSERT INTO TQP_GDS_CHAIN (FACTORY, DEVICE_ID, CHAIN_SEQ, CHAIN_CODE, CHAIN_STATUS, CREATE_USER, CREATE_TIME)
      VALUES ('&factory', '&device', s, c, 'ACTIVE', 'USER', SYSDATE);
    INSERT INTO TQP_GDS_CHAIN_VER (FACTORY, DEVICE_ID, CHAIN_SEQ, VERSION_NO, CHAIN_NAME, COLOR_ARGB, APPLY_LAYER_RULES, CELL_SIZE, VERSION_STATUS, IS_CURRENT, CREATE_USER, CREATE_TIME)
      VALUES ('&factory', '&device', s, 1, 'TSVDC_TOP1_P_FH', -65536, 0, 10, 'READY', 1, 'USER', SYSDATE);
    INSERT INTO TQP_GDS_CHAIN_LAYER (FACTORY, DEVICE_ID, CHAIN_SEQ, VERSION_NO, LAYER_ID, DATA_TYPE) VALUES ('&factory', '&device', s, 1, 3, 0);
    INSERT INTO TQP_GDS_CHAIN_LAYER (FACTORY, DEVICE_ID, CHAIN_SEQ, VERSION_NO, LAYER_ID, DATA_TYPE) VALUES ('&factory', '&device', s, 1, 5, 0);
    INSERT INTO TQP_GDS_CHAIN_LAYER (FACTORY, DEVICE_ID, CHAIN_SEQ, VERSION_NO, LAYER_ID, DATA_TYPE) VALUES ('&factory', '&device', s, 1, 775, 237);
    INSERT INTO TQP_GDS_CHAIN_MEMBER (FACTORY, DEVICE_ID, CHAIN_SEQ, VERSION_NO, PLACED_ELEMENT_ID, ROLE_CODE, INCLUSION_SOURCE, MARKER_X, MARKER_Y)
      VALUES ('&factory', '&device', s, 1, 'R0/E17264', 'INPUT', 'ENDPOINT', UTL_RAW.CAST_TO_BINARY_DOUBLE(HEXTORAW('C0C4C80000000000')), UTL_RAW.CAST_TO_BINARY_DOUBLE(HEXTORAW('40CCA94AE147AE14')));
    DBMS_OUTPUT.PUT_LINE('생성: ' || 'TSVDC_TOP1_P_FH' || ' (Code ' || c || ')');
  END IF;
END;
/
