-- 3) 건수 확인 후 COMMIT (원본과 다르면 되돌린다)
DECLARE
  made NUMBER := 0; skipped NUMBER := 0;
  PROCEDURE chk(p_seq NUMBER, p_name VARCHAR2, p_mem NUMBER, p_edit NUMBER, p_layer NUMBER) IS m NUMBER; e NUMBER; l NUMBER; BEGIN
    IF p_seq IS NULL THEN skipped := skipped + 1; RETURN; END IF;
    SELECT COUNT(*) INTO m FROM TQP_GDS_CHAIN_MEMBER WHERE FACTORY = '&factory' AND DEVICE_ID = '&device' AND CHAIN_SEQ = p_seq;
    SELECT COUNT(*) INTO e FROM TQP_GDS_CHAIN_EDIT WHERE FACTORY = '&factory' AND DEVICE_ID = '&device' AND CHAIN_SEQ = p_seq;
    SELECT COUNT(*) INTO l FROM TQP_GDS_CHAIN_LAYER WHERE FACTORY = '&factory' AND DEVICE_ID = '&device' AND CHAIN_SEQ = p_seq;
    IF m <> p_mem OR e <> p_edit OR l <> p_layer THEN RAISE_APPLICATION_ERROR(-20010, p_name || ' 건수 다름: 도형 ' || m || '/' || p_mem || ' 편집 ' || e || '/' || p_edit || ' Layer ' || l || '/' || p_layer); END IF;
    made := made + 1; DBMS_OUTPUT.PUT_LINE('확인: ' || p_name || ' 도형 ' || m || ' / 편집 ' || e || ' / Layer ' || l);
  END;
BEGIN
  chk(:S_A, 'TSVDC_TOP1_P_FH', 3732, 2116, 3);
  chk(:S_D, 'TSVDC_TOP1_N_FH', 3612, 2116, 3);
  chk(:S_F, 'TSVDC_R_P_FH', 3413, 1692, 3);
  chk(:S_H, 'TSVDC_L_N_FH', 3613, 1832, 3);
  chk(:S_I, 'TSVDC_TOP2_P_FH', 3662, 2088, 3);
  chk(:S_K, 'TSVDC_ASIC1_P_FH', 3568, 2024, 3);
  chk(:S_L, 'TSVDC_ASIC1_N_FH', 3538, 2008, 3);
  chk(:S_M, 'TSVDC_ASIC2_P_FH', 3568, 2024, 3);
  chk(:S_N, 'TSVDC_ASIC2_N_FH', 3538, 2008, 3);
  chk(:S_O, 'TSVDC_ASIC3_P_FH', 3568, 2024, 3);
  chk(:S_P, 'TSVDC_ASIC3_N_FH', 3538, 2008, 3);
  chk(:S_Q, 'TSVDC_ASIC4_P_FH', 3568, 2024, 3);
  chk(:S_S, 'TSVDC_ASIC_HBM_P_FH', 1956, 1158, 3);
  chk(:S_V, 'TSVDC_HBM_C_N_FH', 1709, 852, 3);
  chk(:S_X, 'TSVDC_HBM1_P_FH', 6379, 3500, 3);
  chk(:S_Y, 'TSVDC_HBM0_N_FH', 5908, 3244, 3);
  chk(:S_AA, 'TSVDC_BOT1_P_FH', 1817, 1020, 3);
  chk(:S_AB, 'TSVDC_BOT1_N_FH', 1809, 1020, 3);
  chk(:S_AD, 'TSVDC_BR_FH', 113, 52, 3);
  DBMS_OUTPUT.PUT_LINE('결과: 생성 ' || made || ' / 건너뜀 ' || skipped);
END;
